function personDrafts(before: GameState, after: GameState): Draft[] {
  const previous = new Map(before.houses.map(house => [house.buildingId, house]));
  // SMOOTH-2E: the buildings' and the heads' lookups (and a record's base) are made only when a record is written —
  // most ticks write none, and these were rebuilt for every house each tick.
  let buildings: Map<string, GameState["buildings"][number]> | null = null;
  let heads: Map<string, string> | null = null;
  const headOf = (householdId: string) => {
    if (heads === null) {
      heads = new Map();
      for (const person of before.persons?.people ?? []) if (person.role === "head") heads.set(person.householdId, person.id);
      for (const person of after.persons?.people ?? []) if (person.role === "head") heads.set(person.householdId, person.id);
    }
    return heads.get(householdId);
  };
  const drafts: Draft[] = [];
  const placeOf = (householdId: string) => {
    buildings ??= new Map(after.buildings.map(building => [building.id, building]));
    const building = buildings.get(householdId);
    return building === undefined ? {} : { place: { tx: building.tx, ty: building.ty, buildingId: building.id } };
  };
  for (const house of after.houses) {
    const old = previous.get(house.buildingId);
    if (old === undefined) continue;
    const baseOf = () => {
      const household = { type: "household" as const, id: house.buildingId };
      const head = headOf(house.buildingId);
      return { tick: after.tick, kind: "person" as const, ...placeOf(house.buildingId),
        ...(head === undefined ? { subject: household } : { subject: { type: "person" as const, id: head }, actors: [household] }) };
    };
    const push = (template: string, severity: HistorySeverity, extra: Partial<Draft> = {}) => drafts.push({ ...baseOf(), template, severity, ...extra });
    if (house.burntTick !== undefined && old.burntTick === undefined) {
      push("person.burnt", 1, house.burntByEventId === undefined ? {} : { cause: eventCause(house.burntByEventId, house.burntByEventId.split("@")[0] ?? "fire") });
      continue;
    }
    if (house.burntTick === undefined && old.burntTick !== undefined) push("person.rebuilt", 0);
    if (house.abandonedTick !== undefined && old.abandonedTick === undefined) { push("person.left", 1); continue; }
    if (house.abandonedTick === undefined && old.abandonedTick !== undefined) push("person.resettled", 0);
    if (house.leavingSinceTick !== undefined && old.leavingSinceTick === undefined) push("person.leaving", 0);
    if (old.residents <= 0 && house.residents > 0 && old.abandonedTick === undefined) push("person.move_in", 0);
    if (old.residents > 0 && house.residents <= 0 && house.abandonedTick === undefined) push("person.emptied", 1);
    if (house.level > old.level && house.burntTick === undefined) push("person.level_up", 0, { params: { level: house.level } });
    if (house.level < old.level && house.burntTick === undefined) push("person.level_down", 0, { params: { level: house.level } });
    if (house.leavingSinceTick === undefined && old.leavingSinceTick !== undefined && house.abandonedTick === undefined) push("person.stayed", 0);
    if (house.foodShortSinceTick !== undefined && old.foodShortSinceTick === undefined) push("person.hungry", 0);
    if (house.foodShortSinceTick === undefined && old.foodShortSinceTick !== undefined && house.abandonedTick === undefined) push("person.fed", 0);
    if (house.hasWater !== old.hasWater) push(house.hasWater ? "person.water" : "person.water_lost", 0);
    // Without persons (a town before save v16's first tick) the household's size is its own line.
    if (after.persons === undefined) {
      if (old.residents > 0 && house.residents > old.residents) push("person.grew", 0, { params: { residents: house.residents } });
      if (house.residents > 0 && house.residents < old.residents) push("person.shrank", 0, { params: { residents: house.residents } });

const was = new Map(before.persons.people.map(person => [person.id, person]));
const now = new Map(after.persons.people.map(person => [person.id, person]));
const personRecord = (person: Person, template: string, severity: HistorySeverity, params?: Readonly<Record<string, number | string>>) => drafts.push({
  tick: after.tick, kind: "person", template, severity, subject: { type: "person", id: person.id },
  ...(person.householdId === "manor" ? {} : { actors: [{ type: "household", id: person.householdId }] }), ...placeOf(person.householdId),
  ...(params === undefined ? {} : { params }) });
for (const person of after.persons.people) {
  const old = was.get(person.id);
  if (old === undefined) {
    // PERSON-1a (LN-4): the birth names the parents and where the child's name came from.
    if (person.role === "child" && person.birthYear === year) personRecord(person, "person.born", 0, {
      ...(person.motherId === undefined ? {} : { motherId: person.motherId }), ...(person.fatherId === undefined ? {} : { fatherId: person.fatherId }),
      nameFrom: person.nameFrom ?? "common", ...(person.godparentId === undefined ? {} : { godparentId: person.godparentId }) });
    else if (person.role === "spouse") personRecord(person, "person.married", 0);
    else if (person.role === "kin") personRecord(person, "person.arrived", 0);
    else if (person.role === "steward") personRecord(person, "person.steward", 1);
    continue;
  }
  if (year - person.birthYear >= 14 && beforeYear - old.birthYear < 14) personRecord(person, "person.came_of_age", 0);
  if (old.occupation !== person.occupation && old.occupation !== "child" && person.occupation !== "labourer") personRecord(person, "person.occupation", 0, { occupation: person.occupation });
  if (!old.tags.includes("reeve") && person.tags.includes("reeve")) personRecord(person, "person.reeve", 1);
  // PERSON-1a (LN-10): the passing states and the bailiff's office.
  if (!old.tags.includes("bailiff") && person.tags.includes("bailiff")) personRecord(person, "person.bailiff", 1);

export interface House {
  buildingId: string;
  level: number;
  builtLevel?: number;
  residents: number;
  hasWater: boolean;
  breadStock: number;
  lastServicedTick: number;
  emptyFoodTicks?: number;
  starvationGraceUntilTick?: number;
  unmetRequirementTicks: number;
  promotionTicks?: number;
  /** LB-1 (save v11). Absent only before the first housing update of a house built this tick. */
  members?: HouseholdMembers;
  /** LB-8 (save v11): slots that hold a product, by slot index. Absent = every slot empty. */
  crafts?: readonly HouseholdSlot[];
  /** FP-3 (save v12): the household has been short of food since this tick without a break. Absent = fed. */
  foodShortSinceTick?: number;
  /** FP-3 stage 1 (save v12): the household has been preparing to leave since this tick (`떠날 준비`). */
  leavingSinceTick?: number;
  /** FP-3 stage 2 (save v12): the household left at this tick; the house stands empty and pays no rent (not demolished). */
  abandonedTick?: number;
  /** FP-4 (save v12): the winter ration's carried fraction, thousandths of a bread (0–999). Absent = 0. */
  winterRationCarry?: number;
  /**
   * F0-B EV-4 (save v13): the house burnt at this tick. It stands roofless: level 0, no rent, no promotion; its household
   * stays and eats. A rebuild site (`rebuildOf`) clears it. Absent = not burnt.
   */
  burntTick?: number;
  /** F0-B (save v13): the event (`EventRecord.id`) that burnt it, the cause the player reads (SourceRef type `event`). */
  burntByEventId?: string;
  /** C4 (AL-5, save v23): the household drank ale from an alehouse and counts as served until this tick. */
  aleUntilTick?: number;
}

// FC-2: in the famine the poorest households cannot buy bread at its price (relief or price control feeds them).
const famineShort = new Set(famineShortHouses(state));
let changed = false;
let leaving = 0;
let abandoned = 0;
const houses = state.houses.map(house => {
  if (house.abandonedTick !== undefined) return house;
  // A house that starved empty is an ordinary empty house (the old rule): it has no household to be short or leave.
  if (!householdShortOfFood(house, reserveShort, tick) && !(famineShort.has(house.buildingId) && house.residents > 0)) {
    if (house.foodShortSinceTick === undefined && house.leavingSinceTick === undefined) return house;
    changed = true;
    return withoutPressure(house);
  }
  const since = house.foodShortSinceTick ?? tick;
  if (house.leavingSinceTick === undefined && tick - since >= SEASON) {
    changed = true; leaving += 1;
    return { ...house, foodShortSinceTick: since, leavingSinceTick: tick };
  }
  if (house.foodShortSinceTick === undefined) { changed = true; return { ...house, foodShortSinceTick: since }; }
  return house;
});
// Stage 2: households a season into stage 1 leave, the worst fed first, up to the season's cap and never leaving
// fewer than `minOccupiedHouses` homes lived in (stage 2 is a loss, not the end of the town).
const occupied = houses.filter(house => house.residents > 0).length;
// FC-2: the famine answer moves the season's cap (relief 1, speculation 3).
const cap = departureCapPerSeason(state, PRESSURE_BALANCE.maxDeparturesPerSeason);
const room = Math.max(0, Math.min(cap - tally.departures, occupied - PRESSURE_BALANCE.minOccupiedHouses));
const due = houses
  .map((house, index) => ({ house, index }))
  .filter(({ house }) => house.leavingSinceTick !== undefined && house.abandonedTick === undefined && tick - house.leavingSinceTick >= SEASON)
  .sort((a, b) => a.house.breadStock - b.house.breadStock || a.house.level - b.house.level || a.house.buildingId.localeCompare(b.house.buildingId))
  .slice(0, room);
for (const { house, index } of due) houses[index] = abandonHouse(house, tick);
let resettled = 0;
if (!reserveShort) {
  const lots = new Map(state.buildings.map(building => [building.id, building]));
  // F3-A (PL-3): a house the pestilence emptied waits for its resettlement (`plague.ts`), not for the ladder's household.
  const held = state.plague?.first !== undefined && state.plague.endedTick === undefined ? new Set(state.plague.vacantHouseIds) : null;
  const index = houses.findIndex(house => house.abandonedTick !== undefined && house.hasWater && tick - house.abandonedTick >= PRESSURE_BALANCE.resettleAfterTicks
    && held?.has(house.buildingId) !== true);
  const house = houses[index];
  if (house !== undefined) {
    const { abandonedTick: _abandoned, ...rest } = house;
    houses[index] = { ...rest, residents: houseLotArea(lots.get(house.buildingId)) };
    resettled = 1;
  }
}
if (due.length > 0 || resettled > 0) changed = true;
return {
  houses, changed,

  return {
    originBuildingId: origin.id,
    state: { ...state, events: { ...events, burning: [...events.burning, burningEntry(state, origin, eventId, state.tick)] } },
  };
}

/** EV-4: a burnt house — level and larder lost, rent-free, no promotion; the household stays. F2-A: the raid burns so too. */
export function burntHouse(house: House, tick: number, eventId: string): House {
  const { promotionTicks: _promotion, ...rest } = house;
  return { ...rest, level: 0, builtLevel: 0, breadStock: 0, unmetRequirementTicks: 0, burntTick: tick, burntByEventId: eventId };
}

/** EV-6: a completed rebuild clears the house's burnt state; its household moves back in at level 0. */
export function completeRebuild(house: House): House {
  const { burntTick: _tick, burntByEventId: _event, ...rest } = house;
  return rest;
}

seasonLedgerHistory: 8,
/** FP-3: households are checked for a food shortage every this many ticks (divides a season and a meal interval). */
sampleTicks: 50,
/** FP-3: at most this many households leave (stage 2) per calendar season (F3: "필지 1~2개 황폐"). */
maxDeparturesPerSeason: 2,
/**
 * FP-3: stage 2 never leaves fewer than this many homes lived in — the opening village's four. Two departures from
 * a four-home village leave too few adults to staff its mill, and the town starves empty (seed 5, first winter).
 */
minOccupiedHouses: 4,
/** FP-3: an abandoned house stands empty at least this long before a new household may take it. */
resettleAfterTicks: BALANCE.TICKS_PER_YEAR / 4,
/** FP-4: bread a household eats in winter, permille of its ration (heating stands in for fuel, which is not a resource). */
winterRationPermille: 1200,
/** FP-4: in-year tick where winter starts (the calendar's fourth season; arable growth stops there too). */

/**
 * FIX-12 (item 4, spec docs/design/history-ledger.md HL-1a, QA-010): a ledger record names a person by id; the name —
 * with the epithet the person has now (큰/작은) — is drawn when the record is read, never kept as text.
 */
import { PERSON_NAME_FALLBACK } from "../content/historyCopy.ko";
import type { GameState } from "./engine.types";
import type { HistoryParams, HistoryRecord } from "./history.types";
import { personDisplayName } from "./persons";
import type { Person } from "./persons.types";

/**
 * FIX-12 (item 4, HL-1a, QA-010): the parameters that name a person by id, and the name each one gives the sentence.
 * A record keeps the id; the name (with its epithet as it is now — 큰/작은) is drawn when the record is read.
 */
const PERSON_PARAMS: Readonly<Record<string, string>> = {
  lordId: "lord", guardianId: "guardian", candidateId: "candidate", heirId: "heir", mayorId: "mayor", leaderId: "leader", predecessorId: "predecessor",
  // LM-E4: the steward of an estate (an estate person).
  stewardId: "steward",

export function historyParams(record: Pick<HistoryRecord, "params">, state?: PersonReader): HistoryParams {
  const params = record.params ?? {};
  if (!namesPerson(record)) return params;
  const named: Record<string, string | number> = { ...params };
  for (const [idKey, nameKey] of Object.entries(PERSON_PARAMS)) {
    const id = params[idKey];
    if (typeof id !== "string") continue;
    const person = state === undefined || id === "" ? undefined : personNamed(state, id);
    named[nameKey] = person !== undefined ? personDisplayName(person) : typeof params[nameKey] === "string" ? params[nameKey] : PERSON_NAME_FALLBACK[nameKey] ?? "";
  }
  return named;
}
